      en: ["The Rizal Monument is guarded 24/7 by a ceremonial honor guard.", "The independence of the Philippines from the US was officially proclaimed here in 1946.", "It includes a giant relief map of the Philippine archipelago in an artificial lake.", "It hosted the world's largest papal gathering in 2015 during Pope Francis's visit.", "The flag at Luneta is flown on the tallest flagpole in the country.", "The Japanese and Chinese Gardens within the park are popular spots for relaxation.", "The area's original name during the Spanish era was Bagumbayan."],
      es: ["El Monumento a Rizal es custodiado las 24 horas por una guardia de honor ceremonial.", "Aquí se proclamó oficialmente la independencia de Filipinas de los EE. UU. en 1946.", "Contiene un enorme mapa en relieve del archipiélago filipino en un lago artificial.", "Aquí tuvo lugar en 2015 la misa papal más grande de la historia con el Papa Francisco.", "La bandera en Luneta ondea en el mástil más alto del país.", "Los jardines japonés y chino en el parque son lugares populares para la relajación.", "El nombre original de la zona durante la época española era Bagumbayan."],
      pt: ["O monumento a Rizal é guardado 24 horas por dia por uma guarda de honra cerimonial.", "Aqui foi oficialmente proclamada a independência das Filipinas dos EUA em 1946.", "Contém um enorme mapa em relevo do arquipélago filipino num lago artificial.", "Aqui realizou-se em 2015 a maior missa papal da história com o Papa Francisco.", "A bandeira em Luneta flutua no mastro mais alto do país.", "Os jardins japonês e chinês no parque são locais populares para relaxamento.", "O nome original da área durante o período espanhol era Bagumbayan."],
      fr: ["Le monument Rizal est gardé 24 heures sur 24 par une garde d'honneur cérémonielle.", "L'indépendance des Philippines vis-à-vis des États-Unis y fut officiellement proclamée en 1946.", "Contient une immense carte en relief de l'archipel philippin dans un lac artificiel.", "La plus grande messe papale de l'histoire y fut célébrée par le pape François en 2015.", "Le drapeau de Luneta flotte sur le plus haut mât du pays.", "Les jardins japonais et chinois du parc sont des lieux de détente très appréciés.", "Le nom original de la zone à l'époque espagnole était Bagumbayan."],
