      es: "Una iglesia católica romana bajo el patrocinio de la Orden de San Agustín en Intramuros, Manila.",
      pt: "Uma igreja católica romana sob o patrocínio da Ordem de Santo Agostinho em Intramuros, Manila.",
      fr: "Une église catholique romaine sous le patronage de l'Ordre de Saint Augustin à Intramuros, Manille.",
