      ro: ["Cea mai veche clădire de piatră din Filipine.", "Sit al Patrimoniului Mondial UNESCO.", "Finalizată în 1607."],
      en: ["The oldest stone church in the Philippines.", "A UNESCO World Heritage Site.", "Completed in 1607."],
      es: ["El edificio de piedra más antiguo de Filipinas.", "Patrimonio de la Humanidad por la UNESCO.", "Se terminó de construir en 1607."],
      pt: ["O edifício de pedra mais antigo das Filipinas.", "Património Mundial da UNESCO.", "Foi concluída em 1607."],
      fr: ["Le plus ancien bâtiment en pierre des Philippines.", "Un site du patrimoine mondial de l'UNESCO.", "A été achevée en 1607."],
